glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 color;
out vec2 uv0;
highp vec4 vert(){
  vec4 pos = vec4(a_position,1);
  pos = cc_matViewProj * pos;
  uv0 = a_texCoord;
  color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
in vec4 color;
in vec2 uv0;
layout(std140) uniform Dissolve{
  float dissolveThreshold;
};
#if USE_TEXTURE
  uniform sampler2D u_dissolveMap;
  uniform sampler2D cc_spriteTexture;
#endif
vec4 frag(){
  vec4 o = vec4(1, 1, 1, 1);
  float value = 1.0;
  #if USE_TEXTURE
    vec4 dissolveMap = texture(u_dissolveMap,uv0);
    value *= dissolveMap.r;
  #endif
  if(value < dissolveThreshold){
    discard;
  }
  #if USE_TEXTURE
    vec4 spTexture = texture(cc_spriteTexture,uv0);
    if(spTexture.a <= 0.0){
      discard;
    }
    o *= spTexture;
  #endif
  o *= color;
  if(value < dissolveThreshold + 0.05){
    o = vec4(0.9,0.6,0.3,o.a);
  }
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

glsl1.vert:
precision highp float;
uniform highp mat4 cc_matViewProj;
attribute vec3 a_position;
attribute vec2 a_texCoord;
attribute vec4 a_color;
varying vec4 color;
varying vec2 uv0;
highp vec4 vert(){
  vec4 pos = vec4(a_position,1);
  pos = cc_matViewProj * pos;
  uv0 = a_texCoord;
  color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl1.frag:
precision highp float;
varying vec4 color;
varying vec2 uv0;
  uniform float dissolveThreshold;
#if USE_TEXTURE
  uniform sampler2D u_dissolveMap;
  uniform sampler2D cc_spriteTexture;
#endif
vec4 frag(){
  vec4 o = vec4(1, 1, 1, 1);
  float value = 1.0;
  #if USE_TEXTURE
    vec4 dissolveMap = texture2D(u_dissolveMap,uv0);
    value *= dissolveMap.r;
  #endif
  if(value < dissolveThreshold){
    discard;
  }
  #if USE_TEXTURE
    vec4 spTexture = texture2D(cc_spriteTexture,uv0);
    if(spTexture.a <= 0.0){
      discard;
    }
    o *= spTexture;
  #endif
  o *= color;
  if(value < dissolveThreshold + 0.05){
    o = vec4(0.9,0.6,0.3,o.a);
  }
  return o;
}
void main() { gl_FragColor = frag(); }
